"""Deterministic generated files: ``index.md`` (catalog) and ``core.md`` (the L0 profile card).

No LLM involved. Output depends only on the vault files, the life map and the date (for "valid
today", "new lately", upcoming deadlines), and contains no timestamps, so it is byte-stable while
those don't change and the local model's cached prompt prefix survives.

The core card is laid out the way people hold a close friend in mind (docs/retrieval.md, "L0:
schema card"): who they are in one breath, their character and values, their current chapter,
the periods of their life story, the people who matter, interests and skills, and open loops.
"""

from __future__ import annotations

import re
from collections.abc import Callable, Iterable
from dataclasses import dataclass, field
from datetime import date, timedelta
from pathlib import Path

from brain.index.temporal import period_end, period_start, valid_at
from brain.tokens import CHARS_PER_TOKEN, estimate_tokens
from brain.vault import gitops
from brain.vault.models import (
    RELATIONSHIP_PREDICATES,
    SELF_ID,
    WIKILINK,
    Fact,
    Intention,
    Observation,
    Page,
    fact_private,
    link_target,
)
from brain.vault.store import SELF_PAGE, Vault

GENERATED_NOTE = "<!-- generated by brain from wiki/ pages; manual edits are overwritten -->"
LINE_CHARS = 160

