# --- helpers -----------------------------------------------------------------------------------


def plain(text: str, titles: dict[str, str]) -> str:
    """Wikilinks as readable names: ``[[x|Sam]]`` → Sam, ``[[orgs/x]]`` → its page title."""

    def repl(m: re.Match[str]) -> str:
        raw = m.group(0)
        if "|" in raw:
            return raw[raw.index("|") + 1 : -2].strip()
        target = m.group(1).strip()
        return titles.get(target, target)

    return WIKILINK.sub(repl, text)


def first_sentence(text: str, limit: int = LINE_CHARS) -> str:
    flat = " ".join(text.split())
    m = re.search(r"(?<=[.!?])\s+(?=[A-Z0-9\[])", flat)
    sentence = flat[: m.start()] if m else flat
    if len(sentence) > limit:
        sentence = sentence[: limit - 1].rsplit(" ", 1)[0] + "…"
    return sentence


def validity_suffix(fact: Fact) -> str:
    """Same wording as the index items, so chat can skip memory hits already in the card."""
    if fact.valid_from and fact.valid_to:
        return f" ({fact.valid_from} to {fact.valid_to})"
    if fact.valid_from:
        return f" (since {fact.valid_from})"
    if fact.valid_to:
        return f" (until {fact.valid_to})"
    return ""


def _titles(pages: list[Page]) -> dict[str, str]:
    titles = {p.id: p.title for p in pages}
    titles[SELF_ID] = titles.get(SELF_PAGE, "the owner")
    return titles


def _visible(pages: list[Page], include_private: bool) -> list[Page]:
    return [p for p in pages if include_private or p.privacy != "private"]


# --- index.md ----------------------------------------------------------------------------------


def build_index(vault: Vault, *, include_private: bool = True) -> str:
    """``- [[id]] — summary`` per wiki page, grouped by the page's first life-map region."""
    pages = _visible(vault.pages(), include_private)
    titles = _titles(pages)
    lifemap = vault.lifemap
    order = list(lifemap.regions)
    groups: dict[str, list[str]] = {}
    for page in sorted(pages, key=lambda p: p.id):
        heading = None
        for region_id in page.regions:
            if region := lifemap.region(region_id):
                heading = region.label or region.id
                break
        heading = heading or TYPE_GROUPS.get(page.type, "Other")
        summary = first_sentence(plain(page.summary, titles)) if page.summary.strip() else ""
        groups.setdefault(heading, []).append(f"- [[{page.id}]] — {summary or page.title}")

    labels = [lifemap.regions[r].label or r for r in order]
    known = [h for h in labels if h in groups]
    rest = sorted(h for h in groups if h not in labels)
    out = ["# Index", "", GENERATED_NOTE]
    for heading in dict.fromkeys(known + rest):
        out += ["", f"## {heading}", "", *groups[heading]]
    return "\n".join(out) + "\n"


# --- core.md: ranking and dedupe ---------------------------------------------------------------


def _salience(fact: Fact) -> float:
    level = fact.extra.get("level", "").strip().casefold()
    return (
        PREDICATE_WEIGHT.get(fact.p, DEFAULT_WEIGHT)
        + KIND_BONUS.get(fact.kind, 0.0)
        + LEVEL_BONUS.get(level, 0.0)
    )


def _recency(fact: Fact) -> str:
    return max(fact.valid_from or "", fact.rec.isoformat())


def _tokens(text: str) -> frozenset[str]:
    words = re.findall(r"[a-z0-9+#]+", text.casefold())
    return frozenset(w[:-1] if len(w) > 3 and w.endswith("s") else w for w in words) - _STOP


def _similar(a: frozenset[str], b: frozenset[str]) -> bool:
    if not a or not b:
        return a == b
    return len(a & b) / len(a | b) >= SIMILAR


@dataclass
class _Group:
    """Near-identical facts merged into one list item."""

    facts: list[Fact]
    tokens: frozenset[str]

    @property
    def best(self) -> Fact:
        return self.facts[0]

    @property
    def score(self) -> float:
        sources = {s for f in self.facts for s in f.src} or {""}
        extra = min(len(sources) - 1, MAX_SOURCE_BONUS)
        return _salience(self.best) + SOURCE_BONUS * extra

    @property
    def recency(self) -> str:
        return max(_recency(f) for f in self.facts)


def _rank(facts: Iterable[Fact], key: Callable[[Fact], str]) -> list[_Group]:
    """Group near-duplicates (same normalised tokens of ``key``), then rank by salience
    (predicate weight, stated > observed > inferred, skill level, number of sources), newest
    first on ties."""
    ordered = sorted(
        facts, key=lambda f: (-_salience(f), _neg(_recency(f)), f.text.casefold(), f.id)
    )
    groups: list[_Group] = []
    for fact in ordered:
        tokens = _tokens(key(fact))
        for group in groups:
            if _similar(tokens, group.tokens):
                group.facts.append(fact)
                break
        else:
            groups.append(_Group([fact], tokens))
    groups.sort(key=lambda g: (-g.score, _neg(g.recency), key(g.best).casefold(), g.best.id))
    return groups


def _neg(text: str) -> tuple[int, ...]:
    """Sort key that orders strings descending inside an ascending sort."""
    return tuple(-ord(c) for c in text) + (1,)


def _lc(text: str) -> str:
    """Lowercase a leading capital unless it starts an acronym ("SQL") or a name-like token."""
    if len(text) > 1 and text[0].isupper() and text[1].islower():
        return text[0].lower() + text[1:]
    return text


def _span(start: str | None, end: str | None) -> str:
    s, e = (start or "")[:4], (end or "")[:4]
    if s and e:
        return s if s == e else f"{s}–{e}"
    if s:
        return f"{s}–now"
    return f"until {e}" if e else "now"


def _overlaps(a: Fact, b: Fact) -> bool:
    """Valid-time intervals overlap (open bounds are open); an undated fact overlaps nothing."""
    if not (a.valid_from or a.valid_to) or not (b.valid_from or b.valid_to):
        return False
    try:
        if a.valid_from and b.valid_to and period_start(a.valid_from) > period_end(b.valid_to):
            return False
        return not (
            b.valid_from and a.valid_to and period_start(b.valid_from) > period_end(a.valid_to)
        )
    except ValueError:
        return False


def _overlap_days(a: Fact, b: Fact) -> int:
    if not _overlaps(a, b):
        return 0
    start = max(period_start(a.valid_from or "0001"), period_start(b.valid_from or "0001"))
    end = min(period_end(a.valid_to or "9999"), period_end(b.valid_to or "9999"))
    return (_day(end) - _day(start)).days + 1


def _day(iso: str) -> date:
    """``period_end`` pads every month to day 31; clamp to a real date."""
    y, m, d = (int(x) for x in iso.split("-"))
    while True:
        try:
            return date(y, m, d)
        except ValueError:
            d -= 1


# --- core.md: layout and budget ----------------------------------------------------------------


@dataclass
class _Row:
    """One card line: ``- Label: a, b, c (+n more)``; list rows shrink to fit the budget."""

    items: list[str]
    label: str = ""
    total: int = 0  # candidates before the cap, for "(+n more)"
    shrink: bool = True
    sep: str = ", "

    def render(self, n: int) -> str:
        more = max(self.total, len(self.items)) - n
        body = self.sep.join(self.items[:n]) + (f" (+{more} more)" if more > 0 else "")
        return f"- {self.label}: {body}" if self.label else f"- {body}"


@dataclass
class _Section:
    heading: str
    rows: list[_Row] = field(default_factory=list)

    def fit(self, budget: int) -> list[str]:
        """Greedy in row order: each row takes as many items as still fit."""
        left = budget - (len(self.heading) + 6)  # "\n## heading\n\n"
        lines: list[str] = []
        for row in self.rows:
            counts = range(len(row.items), 0, -1) if row.shrink else [len(row.items)]
            for n in counts:
                text = row.render(n)
                if len(text) + 1 <= left:
                    lines.append(text)
                    left -= len(text) + 1
                    break
        return lines


def _cost(heading: str, lines: list[str]) -> int:
    return (len(heading) + 6 + sum(len(x) + 1 for x in lines)) if lines else 0


def _list_row(label: str, groups: list[_Group], cap: int, item: Callable[[Fact], str]) -> _Row:
    items = list(dict.fromkeys(item(g.best) for g in groups))
    return _Row(items[:cap], label, total=len(items))


# --- core.md: the builder ----------------------------------------------------------------------


class _Card:
    """Collects the facts the card is made of, once, with privacy and validity applied."""

    def __init__(self, vault: Vault, today: date, include_private: bool) -> None:
        self.vault = vault
        self.today = today
        self.include_private = include_private
        all_pages = vault.pages()
        private = [p for p in all_pages if self._page_private(p) and p.subject != SELF_ID]
        self.private_ids = {p.id for p in all_pages if self._page_private(p)}
        names = {n for p in private for n in (p.title, *p.aliases)}
        names |= {p.title.split()[0] for p in private if p.type == "person" and p.title.split()}
        self.private_names = sorted({n.strip().casefold() for n in names if len(n.strip()) >= 3})
        self.pages = [p for p in all_pages if p.id not in self.private_ids]
        self.titles = _titles(self.pages)
        self.by_id = {p.id: p for p in self.pages}
        self.self_pages = [p for p in self.pages if p.subject == SELF_ID]
        self.self_all = [
            f for p in self.self_pages for f in (*p.facts, *p.history) if self.allowed(f)
        ]
        self.current = [
            f for p in self.self_pages for f in p.facts if self.allowed(f) and self.is_current(f)
        ]
        self.current_ids = {f.id for f in self.current}

    # -- filters ------------------------------------------------------------------------------

    def _page_private(self, page: Page) -> bool:
        if self.include_private:
            return False
        return page.privacy == "private" or self.vault.lifemap.privacy_for(page.regions) == (
            "private"
        )

    def allowed(self, fact: Fact) -> bool:
        if self.include_private:
            return True
        if fact_private(fact):  # from an answer the owner marked private
            return False
        target = link_target(fact.o)
        return not (target and target in self.private_ids) and self.predicate_allowed(fact.p)

    def predicate_allowed(self, p: str) -> bool:
        """False when the life map files ``p`` under a private region (traits, health, ...)."""
        if self.include_private:
            return True
        lifemap = self.vault.lifemap
        for subject in ("self", "person"):
            region = lifemap.region_for(p, subject)
            if region and lifemap.privacy_for([region]) == "private":
                return False
        return True

    def is_current(self, fact: Fact) -> bool:
        try:
            return valid_at(fact.valid_from, fact.valid_to, self.today)
        except ValueError:
            return True

    # -- wording ------------------------------------------------------------------------------

    def name(self, value: str) -> str:
        """An object as a readable name; links to missing pages fall back to their slug."""

        def repl(m: re.Match[str]) -> str:
            raw = m.group(0)
            if "|" in raw:
                return raw[raw.index("|") + 1 : -2].strip()
            target = m.group(1).strip()
            return self.titles.get(target) or target.rsplit("/", 1)[-1].replace("-", " ")

        return " ".join(WIKILINK.sub(repl, value).split())

    def item(self, fact: Fact) -> str:
        """A short list item: the object, or the fact's text when the object is long."""
        obj = self.name(fact.o)
        if len(obj) > 48:
            obj = first_sentence(self.name(fact.text), 60).rstrip(".")
        level = fact.extra.get("level", "").strip()
        return f"{obj} ({level})" if level and fact.p == "has_skill" else obj

    def text(self, fact: Fact) -> str:
        return first_sentence(self.name(fact.text), 90).rstrip(".")

    def facts(self, *predicates: str) -> list[Fact]:
        return [f for f in self.current if f.p in predicates]

    def ranked(self, *predicates: str) -> list[_Group]:
        return _rank(self.facts(*predicates), lambda f: self.name(f.o))

    def best(self, predicate: str) -> Fact | None:
        groups = self.ranked(predicate)
        return groups[0].best if groups else None

    # -- 0. identity --------------------------------------------------------------------------

    def owner_name(self) -> str:
        names = sorted(self.facts("name"), key=lambda f: f.id)
        if names:
            return self.name(names[0].o)
        profile = self.by_id.get(SELF_PAGE)
        if profile and profile.title.strip() and profile.title != "Profile":
            return profile.title
        return "The owner"

    def identity(self) -> str:
        parts = [f"Name: {self.owner_name()}"]
        role, team = self.best("role"), self.best("team")
        orgs = [self.name(g.best.o) for g in self.ranked("works_at")][:2]
        job = self.name(role.o) if role else ""
        if orgs:
            job = f"{job} at {' and '.join(orgs)}" if job else f"works at {' and '.join(orgs)}"
        if team:
            name = self.name(team.o)
            job += f" ({name})" if "team" in name.casefold() else f" ({name} team)"
        parts.append(job.strip())
        if city := self.best("lives_in"):
            parts.append(f"lives in {self.name(city.o)}")
        if home := self.best("hometown"):
            parts.append(f"from {self.name(home.o)}")
        if born := self.best("born"):
            parts.append(f"born {self.name(born.o)}")
        languages = [self.name(g.best.o) for g in self.ranked("speaks")][:4]
        if languages:
            parts.append("speaks " + ", ".join(languages))
        return " · ".join(p for p in parts if p)

    # -- 1. who they are (traits and values) --------------------------------------------------

    def who(self) -> _Section:
        section = _Section("Who they are")
        missing = []
        for p, label, cap, aspect in TRAIT_ROWS:
            groups = self.ranked(p)
            if groups:
                section.rows.append(_list_row(label, groups, cap, self.item))
            elif aspect and self.predicate_allowed(p):
                missing.append(aspect)
        if missing:
            section.rows.append(_Row(missing, "Not known yet"))
        return section

    # -- 2. now (current chapter, working self) -----------------------------------------------

    def projects(self) -> tuple[list[tuple[Page, bool]], list[str]]:
        """Active projects tied to the owner by a current fact (``(page, leads)``, ranked), and
        the names of the others (finished, or tied only by an ended fact)."""
        linked: dict[str, tuple[bool, bool]] = {}  # id → (leads, current link)
        for page in self.pages:
            if page.type != "project":
                continue
            for fact in page.facts:
                if fact.p in ("owner", "stakeholder") and link_target(fact.o) in (
                    SELF_ID,
                    SELF_PAGE,
                ):
                    leads, cur = linked.get(page.id, (False, False))
                    linked[page.id] = (leads or fact.p == "owner", cur or self.is_current(fact))
        for fact in self.self_all:
            target = link_target(fact.o)
            if target in self.by_id and self.by_id[target].type == "project":
                leads, cur = linked.get(target, (False, False))
                linked[target] = (leads, cur or fact.id in self.current_ids)
        active, other = [], []
        for page_id, (leads, cur) in linked.items():
            page = self.by_id[page_id]
            status = self.project_fact(page, "status")
            done = bool(status and _tokens(status) & DONE_STATUS)
            if cur and not done:
                deadline = self.project_fact(page, "deadline") or "9999"
                active.append(((not leads, status is None, deadline, page.title), page, leads))
            else:
                other.append(page.title)
        active.sort(key=lambda x: x[0])
        return [(p, leads) for _, p, leads in active], other

    def project_fact(self, page: Page, predicate: str) -> str | None:
        facts = [f for f in page.facts if f.p == predicate and self.is_current(f)]
        facts.sort(key=lambda f: (_neg(_recency(f)), f.id))
        return self.name(facts[0].o) if facts else None

    def upcoming(self, page: Page) -> str | None:
        """The project's deadline if it falls within DEADLINE_DAYS from today."""
        deadline = self.project_fact(page, "deadline")
        horizon = (self.today + timedelta(days=DEADLINE_DAYS)).isoformat()
        try:
            soon = period_end(deadline or "") >= self.today.isoformat()
            return deadline if soon and period_start(deadline or "") <= horizon else None
        except ValueError:
            return None

    def now(self, active: list[tuple[Page, bool]]) -> _Section:
        section = _Section("Now")
        for page, leads in active[:MAX_PROJECTS]:
            details = []
            if goal := self.project_fact(page, "goal"):
                details.append(f"goal: {_lc(goal)}" if len(goal) <= 70 else "")
            if status := self.project_fact(page, "status"):
                details.append(f"status: {status}")
            deadline = self.project_fact(page, "deadline")
            if deadline and not self.upcoming(page):  # upcoming ones sit in open loops
                details.append(f"due {deadline}")
            info = "; ".join(d for d in details if d)
            verb = "Leads" if leads else "Works on"
            text = f"{verb} {page.title}" + (f" ({info})" if info else "")
            section.rows.append(_Row([text], shrink=False))
        for p, label, cap in (("responsibility", "Responsibilities", 3), ("goal", "Goals", 3)):
            if groups := self.ranked(p):
                section.rows.append(_list_row(label, groups, cap, self.item))
        if minds := self.on_mind():
            section.rows.append(_Row(minds, "On their mind", sep="; "))
        if new := self.new_lately():
            section.rows.append(_Row(new[:3], "New lately", total=len(new), sep="; "))
        return section

    def on_mind(self) -> list[str]:
        if not self.include_private:  # journal lines carry no privacy flag of their own
            return []
        since = self.today - timedelta(days=MIND_DAYS)
        obs: list[Observation] = [
            o
            for o in self.vault.observations()
            if since <= o.day <= self.today and o.importance >= MIND_MIN_IMPORTANCE
        ]
        obs.sort(key=lambda o: (-o.importance, -o.day.toordinal(), o.id))
        return [f"{first_sentence(self.name(o.text), 100)} ({o.day})" for o in obs[:2]]

    def new_lately(self) -> list[str]:
        since = (self.today - timedelta(days=RECENT_DAYS)).isoformat()

        def recent(f: Fact) -> bool:
            try:
                return bool(f.valid_from) and period_start(f.valid_from or "") >= since
            except ValueError:
                return False

        facts = [f for f in self.current if f.p != "name" and recent(f)]
        groups = _rank(facts, lambda f: f.text)
        return [self.text(g.best) + validity_suffix(g.best) for g in groups]

    # -- 3. life story (lifetime periods) -----------------------------------------------------

    def life(self, other_projects: list[str]) -> _Section:
        section = _Section("Life story")
        dated: list[tuple[str, str, str]] = []  # (end, start, line) → newest first
        undated: list[str] = []
        roles = [f for f in self.self_all if f.p == "role"]
        cities = [f for f in self.self_all if f.p == "lives_in"]
        degrees = [f for f in self.self_all if f.p == "degree"]
        attached: set[str] = set()

        def add(start: str | None, end: str | None, what: str, anchor: Fact) -> None:
            near = []
            if anchor.p != "lives_in":
                near = [c for c in cities if _overlaps(c, anchor) or self._both_now(c, anchor)]
            near.sort(key=lambda c: (c.valid_from or "", c.id))
            names = list(dict.fromkeys(self.name(c.o) for c in near))
            attached.update(c.id for c in near)
            where = f" ({' → '.join(names)})" if names else ""
            if start or end:
                key_end = period_end(end) if end else "9999"
                key_start = period_start(start) if start else ""
                dated.append((key_end, key_start, f"{_span(start, end)} · {what}{where}"))
            else:
                undated.append(what + where)

        jobs = self._merged("works_at")
        owner = {r.id: self._best_job(r, jobs) for r in roles}
        for job in jobs:
            mine = [r for r in roles if owner[r.id] is job]
            mine.sort(key=lambda r: (r.valid_from or "", r.id))
            titles = list(dict.fromkeys(self.name(r.o) for r in mine))
            attached.update(r.id for r in mine)
            if not titles and (m := re.search(r"\bas (?:an? )?(.+)$", self.name(job.text))):
                titles = [m.group(1).rstrip(".")]
            if len(titles) > 2:
                titles = [titles[0], "…", titles[-1]]
            title = " → ".join(_cap(t) for t in titles)
            org = self.name(job.o)
            add(job.valid_from, job.valid_to, f"{title}, {org}" if title else org, job)
        schools = self._merged("studied_at")
        school_of = {d.id: self._degree_school(d, schools) for d in degrees}
        for school in schools:
            mine = [d for d in degrees if school_of[d.id] is school]
            attached.update(d.id for d in mine)
            names = list(dict.fromkeys(_cap(self.name(d.o)) for d in mine))
            what = ", ".join([*names, self.name(school.o)])
            start, end = school.valid_from, school.valid_to
            if not (start or end):  # an undated school takes its degrees' period
                starts = [d.valid_from for d in mine if d.valid_from]
                ends = [d.valid_to for d in mine if d.valid_to]
                start, end = min(starts, default=None), max(ends, default=None)
            add(start, end, what if names else f"Studied at {what}", school)
        for fact in sorted(roles + degrees, key=lambda f: f.id):
            if fact.id not in attached and fact.id not in self.current_ids:
                what = _cap(self.name(fact.o))
                if fact.p == "degree" and (at := fact.extra.get("at")):
                    what = f"{what}, {self.name(at)}"
                add(fact.valid_from, fact.valid_to, what, fact)
        for city in sorted(cities, key=lambda f: f.id):
            if city.id not in attached and city.id not in self.current_ids:
                add(city.valid_from, city.valid_to, f"Lived in {self.name(city.o)}", city)

        dated.sort(key=lambda x: (_neg(x[0]), _neg(x[1]), x[2]))
        for _, _, line in dated[:MAX_PERIODS]:
            section.rows.append(_Row([line], shrink=False))
        if undated:
            section.rows.append(_Row(sorted(set(undated)), "Undated", sep="; "))
        worked = _rank(
            [f for f in self.self_all if f.p == "worked_on" and not self._is_project(f)],
            lambda f: self.name(f.o),
        )
        others = list(
            dict.fromkeys([*sorted(other_projects), *(self.item(g.best) for g in worked)])
        )
        if others:
            section.rows.append(_Row(others[:5], "Other projects", total=len(others)))
        return section

    def _best_job(self, role: Fact, jobs: list[Fact]) -> Fact | None:
        """The job a role belongs to: the longest valid-time overlap (back-to-back jobs share a
        boundary year at ``YYYY`` precision), or the current job for an undated current role."""
        best, best_days = None, 0
        for job in jobs:
            if self._both_now(role, job) and not (role.valid_from or role.valid_to):
                return job
            days = _overlap_days(role, job)
            if days > best_days:
                best, best_days = job, days
        return best

    def _degree_school(self, degree: Fact, schools: list[Fact]) -> Fact | None:
        """The school a degree is from: the one its ``at::`` links to. A degree without the link
        (written before it existed, or by hand) goes with the one school whose study period is the
        same as the degree's, else the one where it began whose period contains its date (a degree
        dated by one year, or by a start only, is the year it was awarded) or overlaps its period
        by more than a year.
        A tie, or a shared boundary year between back-to-back schools (preparatory classes ending
        the year the degree starts), is no evidence: the degree is listed on its own. An undated
        degree goes with the only school."""
        if at := degree.extra.get("at"):
            target = link_target(at) or at
            linked = [s for s in schools if (link_target(s.o) or s.o) == target]
            return linked[0] if linked else None
        start, end = degree.valid_from, degree.valid_to
        if not (start or end):
            return schools[0] if len(schools) == 1 else None
        same = [s for s in schools if _span(s.valid_from, s.valid_to) == _span(start, end)]
        if len(same) == 1:
            return same[0]
        point = not (start and end) or start[:4] == end[:4]
        first = degree.model_copy(update={"valid_from": start or end, "valid_to": start or end})
        days = sorted(
            (_overlap_days(first if point else degree, s), i)
            for i, s in enumerate(schools)
            if _overlaps(first, s)  # it began there
        )[::-1]
        enough = days and days[0][0] > (0 if point else YEAR_DAYS)
        if not enough or (len(days) > 1 and days[1][0] == days[0][0]):
            return None
        return schools[days[0][1]]

    def _is_project(self, fact: Fact) -> bool:
        target = link_target(fact.o)
        return bool(target and target in self.by_id and self.by_id[target].type == "project")

    def _both_now(self, a: Fact, b: Fact) -> bool:
        return a.id in self.current_ids and b.id in self.current_ids

    def _merged(self, predicate: str) -> list[Fact]:
        """Facts for one predicate with duplicates of the same object merged into one span."""
        out: list[Fact] = []
        facts = sorted(
            (f for f in self.self_all if f.p == predicate),
            key=lambda f: (f.valid_from or "", f.id),
        )
        for fact in facts:
            tokens = _tokens(self.name(fact.o))
            for i, kept in enumerate(out):
                if not _similar(tokens, _tokens(self.name(kept.o))):
                    continue
                if _overlaps(fact, kept):
                    starts = [d for d in (kept.valid_from, fact.valid_from) if d]
                    ends = [kept.valid_to, fact.valid_to]
                    end = None if None in ends else max(e for e in ends if e)
                    out[i] = kept.model_copy(
                        update={"valid_from": min(starts) if starts else None, "valid_to": end}
                    )
                    break
                if not (fact.valid_from or fact.valid_to):  # an undated restatement
                    break
            else:
                out.append(fact)
        return out

    # -- 4. people who matter -----------------------------------------------------------------

    def people(self) -> _Section:
        found: dict[str, tuple[int, str, int]] = {}  # name → (tier, relation, known facts)

        def note(name: str, p: str, rel: str, known: int, mentee: bool = False) -> None:
            label = rel or ("mentee" if mentee else PERSON_LABEL.get(p, "mentor"))
            tier = PERSON_TIER.get(p, 8)
            if p == "friend_of" and re.search(r"\b(close|best)\b", label.casefold()):
                tier = 2
            old = found.get(name)
            if old is None or (tier, label) < old[:2]:
                found[name] = (tier, label, known)

        for fact in self.current:
            if fact.p in RELATIONSHIP_PREDICATES or fact.p == "manager":
                target = link_target(fact.o)
                page = self.by_id.get(target or "")
                known = len(page.facts) if page else 0
                rel = fact.extra.get("rel", "")
                note(self.name(fact.o), fact.p, rel, known, mentee=fact.p == "mentor_of")
        for page in self.pages:
            if page.type != "person":
                continue
            for fact in page.facts:
                is_self = link_target(fact.o) in (SELF_ID, SELF_PAGE)
                related = fact.p in RELATIONSHIP_PREDICATES and is_self
                if related and self.is_current(fact) and self.allowed(fact):
                    note(page.title, fact.p, fact.extra.get("rel", ""), len(page.facts))
        ranked = sorted(found.items(), key=lambda x: (x[1][0], -x[1][2], x[0]))
        section = _Section("People who matter")
        for name, (_, label, _) in ranked[:MAX_PEOPLE]:
            section.rows.append(_Row([f"{name} ({label})"], shrink=False))
        if len(ranked) > MAX_PEOPLE:
            section.rows.append(_Row([f"+{len(ranked) - MAX_PEOPLE} more people"], shrink=False))
        return section

    # -- 5. interests and skills --------------------------------------------------------------

    def interests(self) -> _Section:
        section = _Section("Interests and skills")
        for predicates, label, cap in (
            (("interest", "likes"), "Interests and likes", 8),
            (("has_skill", "certification"), "Skills", 8),
            (("dislikes",), "Dislikes", 4),
            (("member_of",), "Member of", 3),
        ):
            if groups := self.ranked(*predicates):
                section.rows.append(_list_row(label, groups, cap, self.item))
        return section

    # -- 6. open loops ------------------------------------------------------------------------

    def loops(self, active: list[tuple[Page, bool]]) -> _Section:
        section = _Section("Open loops")
        due = [(d, page.title) for page, _ in active if (d := self.upcoming(page))]
        for deadline, title in sorted(due):
            section.rows.append(_Row([f"{title} due {deadline}"], shrink=False))
        for intention in self.intentions()[:3]:
            when = f" (after {intention.after})" if intention.after else ""
            section.rows.append(_Row([self.text_of(intention.text) + when], shrink=False))
        for question in self.questions()[:2]:
            section.rows.append(_Row([f"To ask: {question}"], shrink=False))
        return section

    def text_of(self, text: str) -> str:
        return first_sentence(self.name(text), 100)

    def intentions(self) -> list[Intention]:
        items = [
            i
            for i in self.vault.intentions()
            if not i.done
            and not any(w in self.private_ids for w in i.when)
            and not self._mentions_private(i.text)
            and not (not self.include_private and self._from_private_episode(i.src))
        ]
        return sorted(items, key=lambda i: (i.after is None, i.after or "", i.id))

    def _from_private_episode(self, src: list[str]) -> bool:
        private = {e.id for e in self.vault.episodes() if e.privacy == "private"}
        return any(s in private for s in src)

    def questions(self) -> list[str]:
        """Open items of ``questions.md``, in file order (the file is kept in priority order).
        An item may continue on indented lines; one marked ``(privacy:: private)`` is never
        shown."""
        path = self.vault.questions_path
        if not path.exists():
            return []
        items: list[list[str]] = []
        for line in path.read_text(encoding="utf-8").splitlines():
            if re.match(r"^\s*[-*]\s+", line):
                items.append([line])
            elif items and line.strip() and line[:1].isspace():
                items[-1].append(line.strip())
            elif items and items[-1]:  # a blank line or a heading ends the item
                items.append([])
        out = []
        for lines in items:
            if not lines:
                continue
            m = re.match(r"^\s*[-*]\s+(\[( |x|X)\]\s+)?(.*)$", " ".join(lines))
            if not m or (m.group(2) or " ") != " ":
                continue
            if re.search(r"\(privacy::\s*private\s*\)", m.group(3)):
                continue
            text = re.sub(r"\s*\^[a-z]-[a-z0-9]+\s*$", "", m.group(3))
            text = re.sub(r"\s*\([a-z_]+::[^)]*\)", "", text).strip()
            text = re.sub(r"\s*\^[a-z]-[a-z0-9]+\s*$", "", text)
            if text and not self._mentions_private(m.group(3)):
                out.append(self.text_of(text))
        return out

    def _mentions_private(self, text: str) -> bool:
        """A link to a private page, or a private page's title or alias as a whole word."""
        if any(m.group(1).strip() in self.private_ids for m in WIKILINK.finditer(text)):
            return True
        low = text.casefold()
        return any(re.search(rf"\b{re.escape(n)}\b", low) for n in self.private_names)


def _cap(text: str) -> str:
    return text[:1].upper() + text[1:]


def build_core(
    vault: Vault,
    *,
    max_tokens: int = 1500,
    today: date | None = None,
    include_private: bool = True,
    target_tokens: int = CORE_TARGET_TOKENS,
) -> str:
    """The L0 card: identity line, then who they are, now, life story, people who matter,
    interests and skills, open loops (empty sections are left out).

    Each section gets a share of ``min(max_tokens, target_tokens)``; what a section leaves
    unused goes to the others in FILL_ORDER, and list rows shrink before they are dropped.
    ``max_tokens`` is a hard cap. ``include_private=False`` leaves out private pages, private
    life-map regions and the journal (the variant for the big model).
    """
    card = _Card(vault, today or date.today(), include_private)
    identity = card.identity()
    active, other = card.projects()
    built = {
        "who": card.who(),
        "now": card.now(active),
        "life": card.life(other),
        "people": card.people(),
        "interests": card.interests(),
        "loops": card.loops(active),
    }

    head = ["# Core", "", GENERATED_NOTE, ""]
    limit = int(min(max_tokens, target_tokens) * CHARS_PER_TOKEN)
    head_cost = len("\n".join(head)) + 1
    identity = identity[: max(limit - head_cost - 1, 0)]
    avail = limit - head_cost - len(identity) - 1
    chosen = {key: built[key].fit(int(avail * share)) for key, _, share in SECTIONS}
    pool = avail - sum(_cost(built[k].heading, lines) for k, lines in chosen.items())
    for key in FILL_ORDER:  # spare budget goes to the sections that were cut, in priority order
        sec = built[key]
        old = _cost(sec.heading, chosen[key])
        lines = sec.fit(old + pool)
        if _cost(sec.heading, lines) > old:
            pool -= _cost(sec.heading, lines) - old
            chosen[key] = lines

    def render() -> str:
        out = [*head, identity]
        for key, heading, _ in SECTIONS:
            if chosen[key]:
                out += ["", f"## {heading}", "", *chosen[key]]
        return "\n".join(out) + "\n"

    text = render()
    while estimate_tokens(text) > max_tokens:  # safety net; the budget above should hold
        key = next((k for k in reversed(FILL_ORDER) if chosen[k]), None)
        if key is None:
            identity = identity[: max(len(identity) - 20, 0)]
        else:
            chosen[key].pop()
        text = render()
    return text


# --- writing -----------------------------------------------------------------------------------


DENYLIST_MARKER = "# --- generated by brain: names of private pages (do not edit below) ---"


def build_denylist(vault: Vault, current: str = "") -> str:
    """``.privacy/denylist.txt``: the owner's manual lines, then the names of private pages.

    Self pages are left out: their titles ("Health", "Traits") are common words, and the owner's
    own name already appears in the public repository (license, author).
    """
    manual = current.split(DENYLIST_MARKER, 1)[0].rstrip("\n")
    names = {
        name.strip()
        for page in vault.pages()
        if page.privacy == "private" and page.subject != SELF_ID
        for name in (page.title, *page.aliases)
        if len(name.strip()) >= 3
    }
    lines = [manual, "", DENYLIST_MARKER, *sorted(names, key=str.casefold)]
    return "\n".join(lines).lstrip("\n") + "\n"


def write_generated(
    vault: Vault, *, max_tokens: int = 1500, today: date | None = None
) -> list[Path]:
    """Rewrite ``index.md``, ``core.md`` and the privacy denylist when their content changed;
    return changed paths."""
    deny = vault.denylist_path
    targets = {
        vault.index_path: build_index(vault),
        vault.core_path: build_core(vault, max_tokens=max_tokens, today=today),
        deny: build_denylist(vault, deny.read_text(encoding="utf-8") if deny.exists() else ""),
    }
    changed = []
    for path, text in targets.items():
        old = path.read_text(encoding="utf-8") if path.exists() else None
        if old != text:
            path.parent.mkdir(parents=True, exist_ok=True)
            tmp = path.with_name(f".{path.name}.tmp")
            tmp.write_text(text, encoding="utf-8")
            tmp.replace(path)
            changed.append(path)
    return changed


def refresh_generated(
    vault: Vault, *, max_tokens: int = 1500, today: date | None = None, commit: bool = True
) -> list[Path]:
    """Regenerate and, if anything changed, commit the vault."""
    changed = write_generated(vault, max_tokens=max_tokens, today=today)
    if changed and commit:
        names = ", ".join(p.name for p in changed)
        gitops.commit_all(vault.root, f"brain: regenerate {names}")
    return changed
